private void enlarge(final int size){
    // If the current capacity is not enough to hold the new data, create a new array with a larger capacity
    if (this.buf.length - this.count < size) {
        // Determine the new capacity
        int newCapacity = this.count + size;
        if (newCapacity < this.buf.length << 1) {
            newCapacity = this.buf.length << 1;
        }
        // Create a new array with the new capacity
        byte[] newBuf = new byte[newCapacity];
        // Copy the contents of the current array to the new array
        System.arraycopy(this.buf, 0, newBuf, 0, this.count);
        // Set the new array as the current array
        this.buf = newBuf;
    }
}

