public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    Set<String> keys = resultMap.keySet();
    int numVertices = keys.size();
    if (numVertices == 0) {
        return;
    }
    Iterator<String> keyIter = keys.iterator();
    List<V> vertices = new ArrayList<>(numVertices);
    while (keyIter.hasNext()) {
        String key = keyIter.next();
        V vertex = resultMap.get(key);
        vertices.add(vertex);
    }
    target.addVertices(vertices);
    int numEdges = numVertices * (numVertices - 1) / 2;
    for (int i = 0; i < numEdges; i++) {
        V from = vertices.get(i);
        V to = vertices.get((i + numVertices - 1) % numVertices);
        target.addEdge(from, to);
    }
}

