private static <T> int writeWithSizeDelay(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
     int size = CodedOutputStream.computeRawVarint32Size(schema.serializedSize(message));
     byte[] data = new byte[size + 1];
     CodedOutputStream cos = CodedOutputStream.newInstance(data, 0);
     cos.writeRawVarint32(size);
     schema.writeTo(message, cos);
     cos.flush();
     out.write(data);
     return size;
}

