 private static String substitute(String value, Properties props) {
   Pattern pattern = Pattern.compile("\\$\\{([^}]+)}");
   Matcher matcher = pattern.matcher(value);
   while (matcher.find()) {
     String key = matcher.group(1);
     String replacement = props.getProperty(key);
     if (replacement != null) {
       value = value.replace(matcher.group(0), replacement);
     }
   }
   return value;
 }

