  bucketsByLabel.get(minLabel).clear();

  // Loop through all labels and move vertices to the bucket with label 0
  for (int label : labels) {
    if (label != minLabel) {
      for (int vertex : bucketsByLabel.get(label)) {
        bucketsByLabel.get(0).add(vertex);
